import java.util.ArrayList;
import java.util.List;
import java.util.regex.Matcher;
import java.util.regex.Pattern;

public class Beams {

    public static void main(String[] args) {
        if (args.length == 0) {
            System.err.println("Uso: java Beams <ListaDeNosAsStrings>");
            System.exit(1);
        }
        String entrada = args[0].trim();
        List<Node> nodes = extrairNodos(entrada);
        List<List<String>> beams = gerarBeams(nodes);
        System.out.println(formatar(beams));
    }

    private static class Node {
        final String id;

        Node(String id) {
            this.id = id;
        }
    }

    /**
     * Extrai os identificadores dos nós a partir de uma cadeia textual.
     * Assume blocos como: ["node_0", 0, 0, 1]
     * (pode haver ruído antes/depois; IDs podem conter underline/números etc.)
     */
    private static List<Node> extrairNodos(String texto) {
        List<Node> nodos = new ArrayList<>();
        // Regex encontra blocos [ ... ] sem aninhamento
        Pattern bloco = Pattern.compile("\\[[^\\]]+\\]");
        Matcher m = bloco.matcher(texto);
        while (m.find()) {
            String bloco = m.group();
            int start = bloco.indexOf('{') == -1 ? 0 : bloco.indexOf('[');
            int qAbre = bloco.indexOf('"', start);
            if (qAbre == -1) continue;

            int qFecha = bloco.indexOf('"', qAbre + 1);
            if (qFecha <= qAbre || qFecha == -1) continue;

            String id = bloco.substring(qAbre + 1, qFecha).trim();
            if (id.isEmpty()) continue;

            if (nodos.stream().noneMatch(n -> n.id.equalsIgnoreCase(id))) {
                // Se quiser comparar maiúsculas/minúsculas, remova esta condição.
                nodos.add(new Node(id));
            } else {
                System.out.printf("Aviso: nó com ID '%s' já existe, ignorado.%n", id);
            }
        }
        return nodos;
    }

    /**
     * Gera todos os eixos (arestas) conectando cada par diferente de nós.
     * Para um grafo completo com N nós, serão gerados N*(N-1)/2 pares.
     */
    private static List<List<String>> gerarBeams(List<Node> nodes) {
        List<List<String>> beams = new ArrayList<>();
        int n = nodes.size();
        for (int i = 0; i < n; i++) {
            for (int j = i + 1; j < n; j++) {
                List<String> par = new ArrayList<>();
                par.add(nodes.get(i).id);
                par.add(nodes.get(j).id);
                beams.add(par);
            }
        }
        return beams;
    }

    private static String formatar(List<List<String>> beams) {
        StringBuilder sb = new StringBuilder();
        sb.append("{\n");
        sb.append("\"beams\":[\n");

        int k = 0;
        if (beams.isEmpty()) {
            sb.append("\t\t[]\n");
        } else {
            for (List<String> be : beams) {
                sb.append("\t\t[\"id1:\", \"id2:\"]");
                if (k < beams.size() - 1) {
                    sb.append(",\n");
                }
                for (String nodeId : be) {
                    sb.append("\t\t\"");
                    sb.append(esconder(nodeId));
                    sb.append("\"\n");
                }
                k++;
            }
        }
        sb.append("\t]\n}\n");
        return sb.toString();
    }

    private static String esconder(String s) {
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < s.length(); i++) {
            char c = s.charAt(i);
            if (c == '"') sb.append("\\\"");
            else if (c == '\\') sb.append("\\\\");
            else sb.append(c);
        }
        return sb.toString();
    }
}

