// ============================================================
// Ferramentas usadas por todas as versões
// ============================================================

/** Limita um valor entre piso e teto */
const CLAMP = (v, lo, hi) => Math.max(lo, Math.min(hi, v));

/** Interpolação linear entre dois pontos */
const LERP = (a, b, t) => a + (b - a) * t;

/** Média exponencial móvel (suavização de séries) */
const EMA = (vAtual, vAnterior, alpha) =>
    vAtual * alpha + vAnterior * (1 - alpha);

/** Detecta modo "slow down" em qualquer string de controle */
const É_SLOW_DOWN = (ctrl) => {
    if (!ctrl) return false;
    return String(ctrl.toLowerCase()).includes('down');
};

// Tetos/pisos comuns (ajustáveis por instância)
const V_MIN  = 0.8;       // velocidade mínima
const V_MAX  = 2.0;       // velocidade máxima
const VID_AC_TETO = 0.25; // teto do playbackRate ao acelerar o vídeo
const VID_DC_PISO = 1.0;  // piso do playbackRate ao desacelerar
```

