// Controls: speechQueue[0].startTime | dubbingMode | maxSpeedControl |
//           speedControl | speakingControlMode | video.playbackRate | userConfiguredSpeed | updateRangeValue
adjustSynchronization_1(currentTime) {
    const q = this.speechQueue;
    if (!q || q.length === 0) return;
    if (this.dubbingMode !== 'advanced') return;

    const proximoInicio = q[0].startTime;
    const diff = proximoInicio - currentTime;
    const maxV = Number(this.maxSpeedControl.value) || V_MAX;
    const usuario = this.userConfiguredSpeed || 1;
    const sensibilidade = 700; // ms: define a conversão do desvio em correção

    // Zona neutra: confiamos no tempo real do usuário
    if (diff >= -sensibilidade && diff <= sensibilidade) {
        this.speedControl.value = usuario;
        if (É_SLOW_DOWN(this.speakingControlMode)) this.video.playbackRate = VID_DC_PISO;
        this.updateRangeValue('speed');
        return;
    }

    const intensidade = Math.abs(diff) / sensibilidade; // 0 ... 1

    if (diff < 0) { // ATRASADO → acelerar
        let alvoVel = usuario + intensidade * (maxV - usuario);
        this.speedControl.value = CLAMP(alvoVel, V_MIN, maxV);
        const impulsoVideo = CLAMP(intensidade * 0.18, -0.03, VID_AC_TETO);
        this.video.playbackRate = CLAMP(this.video.playbackRate + impulsoVideo, 0.5, VID_AC_TETO);
    } else { // ADIANTADO → desacelerar
        const excedente = Math.max(0, (diff - sensibilidade) / sensibilidade);
        let alvoVel = usuario - Math.max(0, excedente) * (usuario - V_MIN);
        this.speedControl.value = CLAMP(alvoVel, V_MIN, V_MAX);
        const impulsoVideo = CLAMP(-Math.max(0, excedente) * 0.12, -0.08, 1.2 - VID_DC_PISO);
        this.video.playbackRate = CLAMP(this.video.playbackRate + impulsoVideo, VID_DC_PISO, 1.25);
    }
    this.updateRangeValue('speed');
}
```

**Por quê:** substitui os limiares fixos (500/1000) por uma função contínua — o ouvinte sente menos "solavancos" e a correção cresce na medida exata do desvio.

