## 📌 Versão 3 — Histerese Assimétrica (Anti-Oscilação)

> Cada troca de regime exige "entrar" por um limial menor e "sair" por um maior — mata o famoso pingue-pongue.

```javascript
// Controls: idênticos + máquina de estados com folgas assimétricas
adjustSynchronization_3(currentTime) {
    const q = this.speechQueue;
    if (!q || q.length === 0) return;
    if (this.dubbingMode !== 'advanced') return;

    const proximoInicio = q[0].startTime;
    const diff = proximoInicio - currentTime;
    const maxV = Number(this.maxSpeedControl.value) || V_MAX;
    const usuario = this.userConfiguredSpeed || 1;

    // ── Folgas (dead zones) de ENTRADA e SAÍDA diferentes ──
    let estado = 'NEUTRO'; // 'FAST' | 'SOFT' | 'DESC'
    const ENTRAR_FAST  = -700;   // só acelera forte abaixo daqui
    const SAIR_FAST    = -200;   // acima daqui, sai do forte
    const ENTRAR_SOFT  = -600;   // zona de aceleração suave (-600 .. -200)
    const SAIR_SOFT    = -200;
    const ENTRAR_DESC  = 600;
    const SAIR_DESC    = 760;    // abaixo daqui, sai da desaceleração

    function definirEstado(d) {
        // saídas têm prioridade
        if (estado === 'DESC' && d < SAIR_DESC) estado = 'NEUTRO';
        if (estado === 'FAST' && d > SAIR_FAST)  estado = 'NEUTRO';
        if (estado === 'SOFT' && d > SAIR_SOFT)  estado = 'NEUTRO';

        // entradas
        if (d <= ENTRAR_FAST && estado !== 'FAST') estado = 'FAST';
        else if (d >= ENTRAR_SOFT && d < -200 && estado !== 'SOFT') estado = 'SOFT';
        else if (d >= ENTRAR_DESC && estado !== 'DESC') estado = 'DESC';
    }
    definirEstado(diff);

    const isDown = É_SLOW_DOWN(this.speakingControlMode);

    if (estado === 'NEUTRO') {
        this.speedControl.value = usuario;
        if (isDown) this.video.playbackRate = VID_DC_PISO;
        this.updateRangeValue('speed');
        return;
    }

    const quanta = estado === 'FAST'
        ? Math.min(-diff / 700, 1)                         // aceleração plenas
        : Math.min(-diff / 500, 0.45);                    // aceleração suave

    let alvoVel;
    if (estado === 'FAST') {
        alvoVel = CLAMP(usuario + quanta * (maxV - usuario), V_MIN, maxV);
    } else { // 'SOFT'
        alvoVel = CLAMP(usuario + quanta * 0.4 * (maxV - usuario), V_MIN, maxV);
    }
    this.speedControl.value = alvoVel;

    const impulsVid = estado === 'FAST'
        ? quanta * 0.16                                    // empurra o vídeo para cima
        : quanta * 0.06;
    if (estado === 'DESC') {
        const metaVid = 1.0 - quanta * 0.22;              // puxa o vídeo para mais lento
        this.video.playbackRate = CLAMP(lerp(this.video.playbackRate, metaVid, 1 - quanta), VID_DC_PISO, 1.2);
    } else {
        this.video.playbackRate = CLAMP(this.video.playbackRate + impulsVid, 0.8, VID_AC_TETO);
    }
    this.updateRangeValue('speed');
}
```

**Por quê:** a histerese impede que mudanças de fração de milissegundo façam o sistema oscilar entre "acelera" e "volta ao normal". As faixas são completamente editáveis — é o jeito mais simples de criar sensações subjetivas diferentes sem tocar em fórmulas.

