## 📌 Versão 4 — Tabela de Curva (LUT) Configurável

> Edite a tabela UMA vez e toda a política de sincronização muda — sem algoritmo.

```javascript
// ============================================================
// Tabelas LUT 100% editáveis. Valores NEGATIVOS = acelerar;
// POSITIVOS   = desacelerar. Altere números e pronto.
// ============================================================
const CURVA_VELOCIDADE = {
    -1100: 1.55, -900: 1.45, -750: 1.35, -600: 1.25, -450: 1.15, -300: 1.08, -150: 1.03,
     0:  1.00,  150:  0.95,  300:  0.88,  450:  0.82,  600:  0.74,  750:  0.66,  900:  0.55,
    1100: 0.48 };

const CURVA_VIDEO = {
    -1100: 1.16, -900: 1.12, -750: 1.08, -600: 1.04, -450: 1.02, -300: 1.01, -150: 1.00,
     0:  1.00,   150:  0.99,   300:  0.96,   450:  0.91,   600:  0.80,   750:  0.70,   900:  0.50,
    1100: 0.40 }; // lado esquerdo = taxas altas (acelerar); direito = baixas (frear)

function chaveMaisProxima(valor, tabela) {
    const ks = Object.keys(tabela).map(Number).sort((a, b) => a - b);
    let antes = Infinity, depois = -Infinity;
    for (const k of ks) { if (valor <= k) antes = k; if (valor >= k) depois = k; }
    const [a, d] = [antes, depois].filter(v => typeof v === 'number' && !isNaN(v));
    return a !== Infinity && d !== Infinity ? [a, d] : [undefined, undefined];
}

function interpEntreChaves(valor, k1, v1, k2, v2) {
    const t = (valor - k1) / (k2 - k1);
    return CLAMP(lerp(v1, v2, t), 0.4, 1.4); // faixa de operação ajustável
}

adjustSynchronization_4(currentTime) {
    const q = this.speechQueue;
    if (!q || q.length === 0) return;
    if (this.dubbingMode !== 'advanced') return;

    const diff = q[0].startTime - currentTime;
    const maxV = Number(this.maxSpeedControl.value) || V_MAX;
    const usuario = this.userConfiguredSpeed || 1;

    // Micro-trust: perto do zero, seguimos o usuário
    if (Math.abs(diff) <= 250) {
        this.speedControl.value = CLAMP(usuario, V_MIN, maxV);
        if (É_SLOW_DOWN(this.speakingControlMode)) this.video.playbackRate = 1.0;
        this.updateRangeValue('speed');
        return;
    }

    const kvV = chaveMaisProxima(diff, CURVA_VELOCIDADE);
    const kvR = chaveMaisProxima(diff, CURVA_VIDEO);

    let alvoVel = 1.0, alvoVid = 1.0;
    if (kvV[0] !== undefined && kvV[1] !== undefined) alvoVel = interpEntreChaves(diff, kvV[0], CURVA_VELOCIDADE[kvV[0]], kvV[1], CURVA_VELOCIDADE[kvV[1]]);
    if (kvR[0] !== undefined && kvR[1] !== undefined) alvoVid  = interpEntreChaves(diff, kvR[0], CURVA_VIDEO[kvR[0]], kvR[1], CURVA_VIDEO[kvR[1]]);

    this.speedControl.value = CLAMP(alvoVel, V_MIN, maxV);
    this.video.playbackRate = CLAMP(alvoVid, 0.45, 1.25);
    this.updateRangeValue('speed');
}
```

**Por quê:** a LUT separa o *comportamento* da *lógica*. Você pode mudar tudo via JSON/const — por exemplo, aumentar a tolerância em dias lentos ou ser mais agressivo quando o áudio engasga — sem reescrever código.

