## 📌 Versão 5 — Mínima Ação Eficaz + Cooldown + Retorno Gradual ao Usuário

> Evita tremor: só movimenta quando o desvio realmente importa, com passos mínimos e retomada suave.

```javascript
// Estados internos por chamada (declaração local da função)
let _ultimoMovimento = 0, _emRetorno = false;
const COOLDOWN_MS       = 180;   // pausa entre movimentos (anti-tremor)
const MICRO_TOLERANCE   = 55;    // abaixo disso = ruído, ignoramos
const PASSO_MAX_VEL     = 0.20;  // máxima variação por chamada
const PASSO_MAX_VIDEO   = 0.045;
function ajustar_5(now) {
    const q = this.speechQueue;
    if (!q || q.length === 0) return;
    if (this.dubbingMode !== 'advanced') return;

    const proximoInicio = q[0].startTime;
    const diff = proximoInicio - now;
    const maxV = Number(this.maxSpeedControl.value) || V_MAX;
    const usuario = this.userConfiguredSpeed || 1;
    const drive = Math.min(Math.abs(diff) / 800, 1);
    const sinal = diff < 0 ? 1 : -1;

    // Meta calculada com a mesma lógica proporcional das demais versões
    let alvoV, alvoR = null;
    if (diff < 0) {
        alvoV = CLAMP(usuario + drive * 0.7 * (maxV - usuario), V_MIN, maxV);
        alvoR = CLAMP(this.video.playbackRate + drive * 0.14, 0.5, 1.2);
    } else {
        alvoV = CLAMP(usuario - drive * 0.5, V_MIN, V_MAX);
        alvoR = CLAMP(this.video.playbackRate - drive * 0.09, 1.0, 1.25);
    }

    // Velocidade: duas estratégias conforme a proximidade da meta
    if (alvoV !== null) {
        if (Math.abs(alvoV - this.speedControl.value) > MICRO_TOLERANCE
            && Date.now() - _ultimoMovimento > COOLDOWN_MS) {
            // fora do cooldown → passo cheio (capped)
            const passo = CLAMP(alvoV - this.speedControl.value, -PASSO_MAX_VEL, PASSO_MAX_VEL);
            this.speedControl.value += passo;
        } else if (Math.abs(alvoV - this.speedControl.value) > MICRO_TOLERANCE) {
            // dentro do cooldown → aproxima devagar (40% por ciclo)
            this.speedControl.value = CLAMP(this.speedControl.value + (alvoV - this.speedControl.value) * 0.4, V_MIN, maxV);
        }
        _ultimoMovimento = Date.now();
    }

    // Vídeo: passos pequenos e cooldown independente
    if (alvoR !== null && Math.abs(alvoR - this.video.playbackRate) > 0.015) {
        const passoV = CLAMP(alvoR - this.video.playbackRate, -PASSO_MAX_VIDEO, PASSO_MAX_VIDEO);
        this.video.playbackRate += passoV;
    }

    // Retorno gradual ao valor configurado pelo usuário (sem choque)
    if (Math.abs(diff) <= 800 && Math.abs(this.speedControl.value - usuario) > 0.03 && !_emRetorno) {
        _emRetorno = true;
        const correcao = CLAMP(usuario - this.speedControl.value, -0.25, 0.25) / 4;
        this.speedControl.value = CLAMP(this.speedControl.value + correcao, V_MIN, maxV);
    }
    if (_emRetorno && Math.abs(this.speedControl.value - usuario) < 0.02) _emRetorno = false;

    this.updateRangeValue('speed');
}
```

**Por quê:** combate o problema mais comum nas primeiras versões: o "zumbido" de oscilações rápidas entre correções microscópicas. Também cria uma experiência confortável ao voltar ao valor do usuário depois que a situação se estabiliza.

