## 📌 Versão 7 — Apacamento (Fade) de Transições + Modo Emergência

> Mudanças nunca "pulam": passam por uma janela de transição suave — exceto em emergências.

```javascript
const JANELA_FADE_MS = 220;   // duração da transição suave
const MUDANCA_MINIMA = 0.02;  // diferenças abaixo disso são ignoradas (economia visual)
let _emFade = null, _origemV = 0, _origemR = 0;

function ajustar_7(now) {
    const q = this.speechQueue;
    if (!q || q.length === 0) return;
    if (this.dubbingMode !== 'advanced') return;

    const proximoInicio = q[0].startTime;
    const diff = proximoInicio - now;
    const maxV = Number(this.maxSpeedControl.value) || V_MAX;
    const usuario = this.userConfiguredSpeed || 1;
    const drive = Math.min(Math.abs(diff) / 800, 1);
    const sinal = diff < 0 ? 1 : -1;
    const isDown = É_SLOW_DOWN(this.speakingControlMode);

    let alvoV, alvoR = null;
    if (diff < 0) { // atrasado
        alvoV = CLAMP(usuario + drive * 0.7 * (maxV - usuario), V_MIN, maxV);
        alvoR = CLAMP(this.video.playbackRate + drive * 0.16, 0.5, 1.2);
    } else { // adiantado
        alvoV = CLAMP(usuario - drive * 0.5, V_MIN, V_MAX);
        alvoR = CLAMP(this.video.playbackRate - drive * 0.09, 1.0, 1.2);
    }

    if (alvoV === null && alvoR === null) {
        // Zona neutra: restaura o valor do usuário
        this.speedControl.value = usuario;
        if (isDown) this.video.playbackRate = 1.0;
        this.updateRangeValue('speed');
        return;
    }

    // Emergência: mudança grande demais espera-se no fade (seria um estalo)
    const urgente = Math.abs(alvoV - this.speedControl.value) > 0.4
                  || Math.abs(alvoR - this.video.playbackRate) > 0.25;

    if (_emFade !== null) {
        // Ainda em transição — ease-out (desacelera no fim para suavidade)
        const idade = Math.max(0, (now - _emFade) / JANELA_FADE_MS);
        const avancou = Math.min(idade, 1);
        const easeOut = 1 - Math.pow(1 - avancou, 2);
        this.speedControl.value = LERP(_origemV, alvoV, easeOut);
        this.video.playbackRate = LERP(_origemR, alvoR, easeOut);
        if (avancou >= 1) { _emFade = null; _origemV = 0; _origemR = 0; }
    } else {
        const muV = Math.abs(alvoV - this.speedControl.value);
        const muR = Math.abs(alvoR - this.video.playbackRate);

        if (!urgente && muV < MUDANCA_MINIMA && muR < MUDANCA_MINIMA * 2) {
            // mudança imperceptível → absorvida silenciosamente (mantém coerência)
        } else if (urgente) {
            // emergência: aplica direto, sem fade (glitch, engasgo de áudio)
            this.speedControl.value = alvoV;
            this.video.playbackRate = alvoR;
        } else {
            // Transição gradual: inicia o fade JÁ nesta amostra (zero pop)
            _emFade = now;
            _origemV = this.speedControl.value;
            _origemR = this.video.playbackRate;
        }
    }
    this.updateRangeValue('speed');
}
```

**Por quê:** elimina o visual "digital" de barras de velocidade pulando de valor. Em cenários críticos, ainda responde na hora — equilíbrio entre conforto e reação rápida.

