function zonaDeDiff(d) {
    if (d >= Z_VERDE.lo && d <= Z_VERDE.hi) return 'VERDE';
    if (d > Z_AMBAR.lo && d < Z_AMBAR.hi)    return 'AMBAR';
    return 'VERMELHO';
}

function ajustar_9(now) {
    const q = this.speechQueue;
    if (!q || q.length === 0) return;
    if (this.dubbingMode !== 'advanced') return;

    const diff = q[0].startTime - now;
    const maxV = Number(this.maxSpeedControl.value) || V_MAX;
    const usuario = this.userConfiguredSpeed || 1;
    const isDown = É_SLOW_DOWN(this.speakingControlMode);
    const zona = zonaDeDiff(diff);

    if (zona === 'VERDE') {
        this.speedControl.value = usuario;
        if (isDown) this.video.playbackRate = VID_DC_PISO;
        this.updateRangeValue('speed');
        return;
    }

    // ── ÂMBAR: microcirurgia ──
    if (zona === 'AMBAR') {
        const desvioRel = Math.min(Math.abs(diff / 350) * 0.12, 0.4); // correção máxima sutil
        const poloVid = diff < 0 ? 0.08 : -0.08; // mesmo sentido da velocidade
        const sinal = diff < 0 ? 1 : -1;

        const passoVel = CLAMP(desvioRel * 0.012 * sinal, -0.02, 0.02);
        this.speedControl.value = CLAMP(this.speedControl.value + passoVel, V_MIN, V_MAX);

        const metaVid = CLAMP(1.0 + desvioRel * poloVid * 0.06, 0.92, 1.2);
        this.video.playbackRate = LERP(this.video.playbackRate, metaVid, Math.min(desvioRel, 0.85));
        this.updateRangeValue('speed');
        return;
    }

    // ── VERMELHO: correção plena (como nas versões base) ──
    const drive = Math.min(Math.abs(diff) / 1000, 1);
    let alvoV;
    if (diff < 0) {
        alvoV = CLAMP(usuario + drive * 0.75 * (maxV - usuario), V_MIN, maxV);
        this.video.playbackRate = CLAMP(this.video.playbackRate + drive * 0.16, 0.5, 1.2);
    } else {
        alvoV = CLAMP(usuario - drive * 0.5, V_MIN, V_MAX);
        this.video.playbackRate = CLAMP(this.video.playbackRate - drive * 0.10, 1.0, 1.2);
