## 📌 Versão 6 — Sincronização Preditiva por Linha do Tempo + Tendência

> Em vez de reagir ao passado, prevê para onde o sistema está indo — e intervém antes de errar feio.

```javascript
let _linhaTempo = null, _mediaGaps = null, _esperadoAgora = null, _residuos = [], _derivaResiduo = 0;

// Constrói (uma vez) os marcos esperados a partir dos gaps reais entre falas;
// filtra outliers pela mediana dos espaçamentos.
function construirLinhaTempo(q) {
    const gaps = [];
    for (let i = 1; i < q.length; i++) gaps.push(q[i].startTime - q[i - 1].startTime);
    if (gaps.length < 4) { _mediaGaps = gaps[0] || 800; return [q[0].startTime + 120]; }
    const ordenados = [...gaps].sort((a, b) => a - b);
    _mediaGaps = ordenados[Math.floor(ordenados.length / 2)];
    const marcos = [q[0].startTime + 120];
    let pos = q[0].startTime + 120;
    for (let j = 1; j < gaps.length; j++) { pos += gaps[j - 1]; marcos.push(pos); }
    _linhaTempo = marcos;
    _esperadoAgora = marcos[marcos.length - 1];
}

function ajustar_6(now) {
    const q = this.speechQueue;
    if (!q || q.length < 1) return;
    if (this.dubbingMode !== 'advanced') return;

    if (!_linhaTempo) construirLinhaTempo(q);

    // "Agora esperado" evolui conforme o ritmo médio; o resíduo mede o quanto estamos desviando
    const diff = q[0].startTime - now;
    const r = now - (_esperadoAgora ?? now);
    _residuos.push(r);
    if (_residuos.length > 15) _residuos.shift();
    _derivaResiduo = EMA(r, _derivaResiduo, 0.15);

    if (_esperadoAgora !== null) _esperadoAgora += (_mediaGaps || 800); // projeção para frente

    // Quanto MAIS o atraso estiver PIORANDO, mais cedo e forte intervimos
    const agravamento = (_derivaResiduo < -80) ? Math.min(-_derivaResiduo * 1.6, 300) : 0;
    const gravidade   = Math.abs(_derivaResiduo);
    const ajusteTend  = Math.min(gravidade / 300 * 200, 200);
    const folgaAtraso = Math.max(300, 500 - ajusteTend);
    const folgaAdianto = Math.max(300, 900 - ajusteTend * 0.8);

    const maxV = Number(this.maxSpeedControl.value) || V_MAX;
    const usuario = this.userConfiguredSpeed || 1;
    const sinal = r < 0 ? 1 : -1; // 1 = atrasado | -1 = adiantado
    const qAtraso = (r - agravamento) < -folgaAtraso;
    const qAdianto = r > folgaAdianto;

    if (qAtraso) {
        const quanta = Math.min(1 - (r - agravamento) / 1100, 1);
        this.speedControl.value = CLAMP(usuario + quanta * (maxV - usuario), V_MIN, maxV);
        this.video.playbackRate = CLAMP(this.video.playbackRate + quanta * 0.18, 0.5, 1.25);
    } else if (qAdianto) {
        const quanta = Math.min(r / 900, 1);
        this.speedControl.value = CLAMP(usuario - quanta * (usuario - V_MIN), V_MIN, V_MAX);
        this.video.playbackRate = CLAMP(this.video.playbackRate - quanta * 0.12, 0.95, 1.2);
    } else {
        // Sem condição crítica: microcorreções contínuas guiadas pela tendência (sem trocas de regime)
        const fator = Math.min(Math.abs(r) / 600, 1);
        const passo = sinal === 1 ? 0.012 : -0.012;
        const direcao = r < 0 ? 1 : -1;
        this.speedControl.value = CLAMP(this.speedControl.value + passo * fator * direcao, V_MIN, V_MAX);
        this.video.playbackRate = CLAMP(this.video.playbackRate + ((r < 0 ? 0.003 : -0.003) * fator), 0.95, 1.05);
    }
    this.updateRangeValue('speed');
}
```

**Por quê:** é a versão mais "inteligente" no sentido de antecipação — percebe quando o desvio está ganhando velocidade e reduz a folga de disparo, entrando em ação preventivamente. Útil em streams com latência variável (rede/jitter).

