adjustSynchronization(currentTime) {
            if (this.speechQueue.length > 0) {
                const nextSpeechTime = this.speechQueue[0].startTime;
                const timeDifference = nextSpeechTime - currentTime;

                if (this.dubbingMode === 'advanced') {
                    const maxSpeed = parseFloat(this.maxSpeedControl.value); // Obtém a velocidade máxima do controle

                    if (timeDifference < 500) { // Dublagem atrasada
                        // Ajuste a velocidade da voz para a velocidade máxima
                        this.speedControl.value = maxSpeed;

                        if (this.speakingControlMode === 'slowDown') {
                            // Aumenta a velocidade do vídeo até 0.85x
                                    this.video.playbackRate = Math.min(this.video.playbackRate + 0.1, 0.2);
                        }
                    } else if (timeDifference > 1000) { // Dublagem adiantada
                        // Define a velocidade da voz para o valor padrão (1.2x)
                        this.speedControl.value = 1.2;

                        if (this.speakingControlMode === 'slowDown') {
                            // Diminui a velocidade do vídeo até 0.85x
                            this.video.playbackRate = Math.max(this.video.playbackRate - 0.1, 1.0);
                        }
                    } else {
                        // Se a dublagem estiver sincronizada, retorne à velocidade configurada pelo usuário
                        this.speedControl.value = this.userConfiguredSpeed;
                        if (this.speakingControlMode === 'slowDown') {
                            this.video.playbackRate = 1.0; // Velocidade padrão do vídeo
                        }
                    }
                    this.updateRangeValue('speed');
                }
            }
        }
